{"command":"python3 -c '
import os, json
data = {}
for root, dirs, files in os.walk("simple_output"):
    for file in files:
        path = os.path.join(root, file)
        try:
            with open(path, "r", encoding="utf-8") as f:
                data[path.replace("simple_output/", "")] = f.read()
        except:
            with open(path, "rb") as f:
                import base64
                data[path.replace("simple_output/", "")] = {"b64": base64.b64encode(f.read()).decode("utf-8")}
with open("bundle.json", "w") as f:
    json.dump(data, f)
'"}

